sql.where:
t.deleted = 0

    AND t.check_no = #{req.checkNo}


    AND t.check_scope = #{req.checkScope}


    AND t.line_no = #{req.lineNo}


    AND t.mat_id = #{req.matId}


    AND t.mat_code = #{req.matCode}


    AND t.mat_name LIKE CONCAT('%', #{req.matName}, '%')


    AND t.req_qty = #{req.reqQty}


    AND t.avail_qty = #{req.availQty}


    AND t.reserved_qty = #{req.reservedQty}


    AND t.issued_qty = #{req.issuedQty}


    AND t.short_qty = #{req.shortQty}


    AND t.alt_mat_id = #{req.altMatId}


    AND t.result = #{req.result}


    AND t.check_time = #{req.checkTime}


    AND t.remark = #{req.remark}


    AND t.create_time = #{req.createTime}
